import{bV as a,aL as e,u as i,G as t}from"./chunks/framework.D_inzUUb.js";const c=JSON.parse('{"title":"Ubuntu 24 解决 AdGuard Home 53 端口被占用问题","description":"","frontmatter":{"title":"Ubuntu 24 解决 AdGuard Home 53 端口被占用问题","date":"2026-05-29T00:00:00.000Z","categories":["技术文档","Linux","AdGuard Home"],"tags":["Ubuntu","AdGuard Home","systemd-resolved","DNS","端口冲突"]},"headers":[],"relativePath":"posts/202605/29-ubuntu24-adguard-home-53-port.md","filePath":"posts/202605/29-ubuntu24-adguard-home-53-port.md","lastUpdated":1780023925000}'),n={name:"posts/202605/29-ubuntu24-adguard-home-53-port.md"};function d(l,s,h,o,p,r){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="ubuntu-24-解决-adguard-home-53-端口被占用问题" tabindex="-1">Ubuntu 24 解决 AdGuard Home 53 端口被占用问题 <a class="header-anchor" href="#ubuntu-24-解决-adguard-home-53-端口被占用问题" aria-label="Permalink to &quot;Ubuntu 24 解决 AdGuard Home 53 端口被占用问题&quot;">​</a></h1><p>Ubuntu 24 默认启用了 <code>systemd-resolved</code>，它会占用 53 端口作为 DNS Stub Listener，导致 AdGuard Home 无法绑定 DNS 端口。</p><p>最常见的报错：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>listen tcp 0.0.0.0:53: bind: address already in use</span></span></code></pre></div><p>或者：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bind: address already in use</span></span></code></pre></div><p>本质上是 <code>systemd-resolved</code> 抢占了 <code>127.0.0.53:53</code>。</p><h2 id="确认是谁占用了-53-端口" tabindex="-1">确认是谁占用了 53 端口 <a class="header-anchor" href="#确认是谁占用了-53-端口" aria-label="Permalink to &quot;确认是谁占用了 53 端口&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tulnp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :53</span></span></code></pre></div><p>如果看到 <code>systemd-resolved</code>，说明就是它在捣鬼。</p><h2 id="推荐方案-禁用-dns-stub-listener-ubuntu-24-最稳定" tabindex="-1">推荐方案：禁用 DNS Stub Listener（Ubuntu 24 最稳定） <a class="header-anchor" href="#推荐方案-禁用-dns-stub-listener-ubuntu-24-最稳定" aria-label="Permalink to &quot;推荐方案：禁用 DNS Stub Listener（Ubuntu 24 最稳定）&quot;">​</a></h2><h3 id="第一步-编辑-resolved-conf" tabindex="-1">第一步：编辑 resolved.conf <a class="header-anchor" href="#第一步-编辑-resolved-conf" aria-label="Permalink to &quot;第一步：编辑 resolved.conf&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/resolved.conf</span></span></code></pre></div><p>找到 <code>#DNSStubListener=yes</code>，修改为：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Resolve]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DNS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1.1.1.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DNSStubListener</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=no</span></span></code></pre></div><ul><li><code>DNSStubListener=no</code>：关闭 53 端口监听，释放给 AdGuard Home</li><li><code>DNS=1.1.1.1</code>：设置一个备用上游 DNS，确保系统自身解析不受影响</li></ul><h3 id="第二步-重建-resolv-conf" tabindex="-1">第二步：重建 resolv.conf <a class="header-anchor" href="#第二步-重建-resolv-conf" aria-label="Permalink to &quot;第二步：重建 resolv.conf&quot;">​</a></h3><p>这是 Ubuntu 24 <strong>非常关键</strong>的一步。</p><p>先删除原来的软链接：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/resolv.conf</span></span></code></pre></div><p>然后指向 systemd-resolved 生成的真实配置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /run/systemd/resolve/resolv.conf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/resolv.conf</span></span></code></pre></div><h3 id="第三步-重启-systemd-resolved" tabindex="-1">第三步：重启 systemd-resolved <a class="header-anchor" href="#第三步-重启-systemd-resolved" aria-label="Permalink to &quot;第三步：重启 systemd-resolved&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-resolved</span></span></code></pre></div><h3 id="第四步-确认-53-端口已释放" tabindex="-1">第四步：确认 53 端口已释放 <a class="header-anchor" href="#第四步-确认-53-端口已释放" aria-label="Permalink to &quot;第四步：确认 53 端口已释放&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tulnp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :53</span></span></code></pre></div><p>正常情况下不应该再看到 <code>127.0.0.53:53</code>。</p><h3 id="第五步-启动-adguard-home" tabindex="-1">第五步：启动 AdGuard Home <a class="header-anchor" href="#第五步-启动-adguard-home" aria-label="Permalink to &quot;第五步：启动 AdGuard Home&quot;">​</a></h3><p>Docker 部署：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>原生安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./AdGuardHome</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h2 id="docker-部署注意事项" tabindex="-1">Docker 部署注意事项 <a class="header-anchor" href="#docker-部署注意事项" aria-label="Permalink to &quot;Docker 部署注意事项&quot;">​</a></h2><p>如果你用 Docker 部署 AdGuard Home，端口映射必须是真正的 53：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;53:53/tcp&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;53:53/udp&quot;</span></span></code></pre></div><p><strong>不要改成 <code>5353:53</code></strong>——大多数设备（路由器、手机等）无法指定 DNS 端口，改了之后 DNS 查询会完全失效。</p><h2 id="备选方案-直接禁用-systemd-resolved" tabindex="-1">备选方案：直接禁用 systemd-resolved <a class="header-anchor" href="#备选方案-直接禁用-systemd-resolved" aria-label="Permalink to &quot;备选方案：直接禁用 systemd-resolved&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-resolved</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-resolved</span></span></code></pre></div><p>这种方式更暴力，但 Ubuntu 24 有时会导致系统自身的 DNS 解析失效，因此<strong>更推荐上面的 <code>DNSStubListener=no</code> 方案</strong>。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>推荐度</th><th>风险</th></tr></thead><tbody><tr><td><code>DNSStubListener=no</code> + 重建 resolv.conf</td><td>⭐⭐⭐⭐⭐</td><td>低，系统 DNS 不受影响</td></tr><tr><td>直接禁用 systemd-resolved</td><td>⭐⭐</td><td>高，可能导致系统 DNS 失效</td></tr></tbody></table><p>核心思路就是：<strong>让 systemd-resolved 别监听 53 端口，把位置让给 AdGuard Home</strong>。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li><a href="https://blog.einverne.info/post/2024/01/adguard-home-53-port-systemd-resolve.html" target="_blank" rel="noreferrer">Einverne - AdGuard Home 53 端口与 systemd-resolved 冲突解决</a></li><li><a href="https://localtonet.com/blog/how-to-self-host-adguard-home" target="_blank" rel="noreferrer">Localtonet - How to Self-Host AdGuard Home</a></li><li><a href="https://ramnode.com/guides/adguard-home" target="_blank" rel="noreferrer">RamNode - AdGuard Home Guide</a></li></ul>`,44)])])}const u=a(n,[["render",d]]);export{c as __pageData,u as default};
